-- Node: chd-tet-spell (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Tet Spell Management","body":"**TET SPELL - HYPERCYANOTIC EPISODE**\n\n**IMMEDIATE INTERVENTIONS (in order):**\n\n**1. KNEE-CHEST POSITION**\nHave parent hold infant with knees to chest. Increases SVR and reduces right-to-left shunt.\n\n**2. CALM THE INFANT**\n• Minimize stimulation\n• Do NOT separate from parent if possible\n• Avoid painful procedures if possible\n\n**3. OXYGEN**\n100% FiO2 (helps somewhat, but cyanosis is from shunting)\n\n**4. MORPHINE**\n[Morphine](#/drug/morphine) 0.1-0.2 mg/kg IV/IM\n• Reduces RVOT spasm and catecholamine surge\n• Also reduces respiratory drive (decreases hyperpnea)\n\n**5. IV FLUID BOLUS**\n10-20 mL/kg NS - increases preload\n\n**6. PHENYLEPHRINE (if refractory)**\n[Phenylephrine](#/drug/phenylephrine) 5-20 mcg/kg IV bolus\n• Alpha-agonist increases SVR\n• Reduces right-to-left shunt\n\n**7. PROPRANOLOL (if still refractory)**\n[Propranolol](#/drug/propranolol) 0.1 mg/kg slow IV push\n• Reduces RVOT spasm\n• Use with caution\n\n**8. KETAMINE**\n[Ketamine](#/drug/ketamine) 1-2 mg/kg IV\n• For procedural sedation or intubation\n• Maintains SVR, good for CHD\n\n**AVOID:** Agitation, excessive crying, volume depletion","citation":[1,6,7],"recommendation":"TET SPELL: Knee-chest position first, then calm infant, O2, morphine 0.1-0.2 mg/kg. If refractory: phenylephrine, propranolol, ketamine.","treatment":{"firstLine":{"drug":"Morphine","dose":"0.1-0.2 mg/kg","route":"IV/IM","frequency":"Once, may repeat","duration":"Single dose","notes":"First-line medication for tet spell. Reduces RVOT spasm and catecholamine surge."},"alternative":{"drug":"Phenylephrine","dose":"5-20 mcg/kg","route":"IV bolus","frequency":"Once, may repeat","duration":"Single dose","notes":"Second-line for refractory tet spell. Increases SVR to reduce shunt."},"monitoring":"Continuous pulse ox, HR, BP. Watch for resolution of cyanosis and return of normal color."},"confidence":"definitive","calculatorLinks":[{"id":"peds-dose","label":"Peds Dose Calculator"}],"safetyLevel":"critical"}'::jsonb
WHERE id = 'chd-tet-spell' AND tree_id = 'chd-peds';

-- Node: chd-tga (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Transposition of Great Arteries","body":"**TRANSPOSITION OF GREAT ARTERIES (TGA)**\n\nMost common cyanotic CHD presenting in the first week of life.\n\n**ANATOMY**\nAorta arises from RV, pulmonary artery from LV. Two parallel circulations with no mixing = incompatible with life unless mixing exists.\n\n**PRESENTATION**\n• Severe cyanosis within hours of birth\n• May be well-appearing initially (ductus still open)\n• Rapid deterioration as ductus closes\n• Minimal response to supplemental O2\n\n**CLASSIC CXR:** \"Egg on a string\" - narrow mediastinum, egg-shaped heart\n\n**CRITICAL: MIXING IS ESSENTIAL**\nSurvival depends on mixing between circuits via:\n• Patent ductus arteriosus (PDA)\n• Atrial septal defect (ASD) or patent foramen ovale (PFO)\n• Ventricular septal defect (VSD) - if present\n\n**EMERGENCY MANAGEMENT**\n1. **PGE1** - Keep ductus open: [Prostaglandin E1](#/drug/prostaglandin-e1) 0.05-0.1 mcg/kg/min\n2. **Balloon atrial septostomy (BAS)** - Emergent procedure by cardiology to create/enlarge ASD\n3. Arterial switch operation (definitive repair) in first 2 weeks","citation":[1,2,6,10],"recommendation":"TGA is DUCTAL-DEPENDENT. Start PGE1 immediately. Emergent cardiology for balloon atrial septostomy. Arterial switch surgery within 2 weeks.","treatment":{"firstLine":{"drug":"Prostaglandin E1 (Alprostadil)","dose":"0.05-0.1 mcg/kg/min","route":"Continuous IV infusion","frequency":"Continuous","duration":"Until surgical intervention","notes":"CRITICAL: Keep ductus open. May cause apnea - be prepared to intubate."},"monitoring":"Continuous SpO2, cardiorespiratory monitor. Watch for apnea (common PGE1 side effect). Serial lactates."},"confidence":"definitive","calculatorLinks":[{"id":"peds-dose","label":"Peds Dose Calculator"}],"safetyLevel":"critical"}'::jsonb
WHERE id = 'chd-tga' AND tree_id = 'chd-peds';

-- Node: chd-coarc (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Coarctation of Aorta","body":"**COARCTATION OF THE AORTA**\n\nNarrowing of aorta, typically just distal to left subclavian artery (juxtaductal).\n\n**PRESENTATION**\n• May be asymptomatic initially with open ductus\n• Shock when ductus closes (typically days 1-14)\n• Weak or absent femoral pulses (PATHOGNOMONIC)\n• Upper extremity hypertension, lower extremity hypotension\n• **BP gradient >20 mmHg arm > leg**\n\n**ASSOCIATED FINDINGS**\n• Bicuspid aortic valve (50%)\n• VSD, other left-sided lesions\n• Turner syndrome (screen females)\n\n**CXR:** Cardiomegaly, pulmonary edema. \"Figure 3 sign\" or rib notching in older children (not neonates).\n\n**ECHO:** Narrowing at isthmus, flow acceleration, may see PDA.\n\n**MANAGEMENT**\n1. **PGE1** to reopen ductus: 0.05-0.1 mcg/kg/min\n2. Treat shock: Fluids cautiously, may need inotropes\n3. Correct acidosis\n4. Surgical repair or catheter intervention","citation":[1,2,8,10],"recommendation":"Coarctation: Weak femorals + arm > leg BP gradient. Start PGE1 to reopen ductus. Surgical repair required.","treatment":{"firstLine":{"drug":"Prostaglandin E1 (Alprostadil)","dose":"0.05-0.1 mcg/kg/min","route":"Continuous IV infusion","frequency":"Continuous","duration":"Until surgical repair","notes":"Reopens ductus to restore lower body perfusion. Watch for apnea."},"alternative":{"drug":"Dopamine or Epinephrine","dose":"Dopamine 5-20 mcg/kg/min OR Epinephrine 0.01-0.1 mcg/kg/min","route":"IV infusion","frequency":"Continuous","duration":"Until hemodynamically stable","notes":"For cardiogenic shock. Use cautiously with coarctation."},"monitoring":"Four-extremity BP trending. Femoral pulses. Lactate clearance. Urine output."},"confidence":"definitive","calculatorLinks":[{"id":"peds-dose","label":"Peds Dose Calculator"}],"safetyLevel":"critical"}'::jsonb
WHERE id = 'chd-coarc' AND tree_id = 'chd-peds';

-- Node: cric-anatomy (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Cricothyroid Membrane Anatomy","body":"[Anatomy Diagram](#/info/cric-anatomy)\n\n**Cricothyroid membrane (CTM):** [1][4]\n• Located between **thyroid cartilage** (above) and **cricoid cartilage** (below)\n• Average size: **9 mm height × 30 mm width**\n• Just large enough for a 6.0 ETT (outer diameter 8.2 mm)\n• Covered by skin, subcutaneous fat, and fascia — NO major vessels directly over CTM\n\n**How to locate (CRITICAL):** [2][4]\n\n**\"Laryngeal handshake\" technique:**\n1. Stand at patient''s side\n2. Grasp larynx with non-dominant hand (thumb + middle finger on each side)\n3. Stabilize between fingers\n4. Use index finger to palpate DOWN from thyroid notch\n\n**EMCRIT tip:** Go from **notch DOWN**, not chin down. The EMCrit method of locating the CTM was validated as superior in an RCT. [2]\n\n**Key structures to avoid:**\n• **Superior thyroid artery/vein** — at superior border of thyroid cartilage\n• **Anterior jugular veins** — lateral to midline\n• **Cricothyroid artery** — crosses CTM superiorly (variable)\n\n**Pearl:** Heavy bleeding is expected and should be **ignored** while placing the airway. This is a **tactile procedure**. [1]","citation":[1,2,4],"next":"cric-equipment","summary":"CTM = 9mm × 30mm between thyroid and cricoid; use laryngeal handshake from notch DOWN; ignore bleeding — this is tactile"}'::jsonb
WHERE id = 'cric-anatomy' AND tree_id = 'cricothyrotomy';

-- Node: diplopia-cn3-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"CN III Palsy Overview","body":"**CN III (Oculomotor) controls most eye movement + pupil.**\n\n**CN III Functions:**\n• Superior rectus (upgaze)\n• Inferior rectus (downgaze)\n• Medial rectus (adduction)\n• Inferior oblique (upgaze in adduction)\n• Levator palpebrae (lid elevation)\n• **Pupillary constriction**\n\n**Complete CN III Palsy:**\n• **\"Down and out\"** eye position\n• **Ptosis** (complete)\n• **Dilated pupil** (if pupil-involving)\n• Loss of accommodation\n\n**⚠️ CRITICAL DISTINCTION:**\n\n| | Pupil-INVOLVING | Pupil-SPARING |\n|---|-----------------|---------------|\n| Pupil | Fixed, dilated | Normal, reactive |\n| Classic cause | **Compressive (aneurysm)** | Microvascular |\n| Urgency | **EMERGENT** | Urgent |\n\n**BUT: This \"rule\" is NOT absolute!** [3][4][6]","citation":[3,4,6],"next":"diplopia-cn3-pupil","summary":"CN III Palsy Overview — review key clinical information before proceeding"}'::jsonb
WHERE id = 'diplopia-cn3-start' AND tree_id = 'diplopia';

-- Node: diplopia-cn4-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"CN IV Palsy Overview","body":"**CN IV (Trochlear) - Superior Oblique Muscle**\n\n**Unique Features:**\n• Longest intracranial course of any CN\n• Only CN that exits dorsally from brainstem\n• Only CN that crosses to supply contralateral muscle\n• **Most vulnerable to trauma**\n\n**Function:**\n• Depression in adduction (looking down and in)\n• Intorsion (rotates top of eye toward nose)\n\n**Clinical Presentation:**\n• **Vertical diplopia** (images stacked)\n• **Compensatory head tilt** to opposite shoulder\n• Trouble reading, going downstairs\n• Hypertropia (affected eye higher)\n\n**Common Causes:**\n1. **Trauma** - most common acquired cause\n2. **Microvascular** - diabetes, HTN\n3. **Congenital** - decompensated childhood palsy\n4. Mass lesion (rare) [5][7]","citation":[5,7],"next":"diplopia-cn4-exam","summary":"CN IV Palsy Overview — review key clinical information before proceeding"}'::jsonb
WHERE id = 'diplopia-cn4-start' AND tree_id = 'diplopia';

-- Node: diplopia-cn4-exam (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Parks-Bielschowsky 3-Step Test","body":"**Parks-Bielschowsky 3-Step Test for CN IV Palsy:**\n\n**Purpose:** Isolate the weak muscle in vertical diplopia\n\n**Step 1: Which eye is higher (hypertropic)?**\n• Right hypertropia = problem with RIGHT SO or LEFT IR\n• Left hypertropia = problem with LEFT SO or RIGHT IR\n\n**Step 2: Does hypertropia worsen in R or L gaze?**\n• Worse in LEFT gaze = SO of higher eye OR IR of lower eye\n• Worse in RIGHT gaze = SO of lower eye OR IR of higher eye\n\n**Step 3: Bielschowsky Head Tilt Test**\n• Tilt head to RIGHT then LEFT shoulder\n• Hypertropia worse with tilt to ONE side\n• Worse with tilt TOWARD higher eye = SO palsy of that eye\n\n**Example: Right CN IV Palsy**\n✓ Right hypertropia\n✓ Worse in LEFT gaze\n✓ Worse with RIGHT head tilt\n\n**Sensitivity:** ~75% for unilateral superior oblique palsy [5][7]","citation":[5,7],"next":"diplopia-cn4-workup","calculatorLinks":[{"id":"diplopia-3step","label":"3-Step Test"}],"summary":"Parks-Bielschowsky 3-Step Test — review key clinical information before proceeding"}'::jsonb
WHERE id = 'diplopia-cn4-exam' AND tree_id = 'diplopia';

-- Node: diplopia-cn6-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"CN VI Palsy Overview","body":"**CN VI (Abducens) - Lateral Rectus Muscle**\n\n**Function:**\n• Abduction ONLY (looking outward)\n\n**Clinical Presentation:**\n• **Horizontal diplopia** (worse at distance)\n• **Esotropia** - affected eye turned IN\n• Cannot abduct affected eye past midline\n• **Face turn toward affected side** (to minimize diplopia)\n\n**Unique Feature - False Localizing Sign:**\n• CN VI has the **longest intracranial course**\n• Tethered at Dorello''s canal (petrous apex)\n• **Stretched by downward brainstem displacement**\n• Can be \"false localizing sign\" of elevated ICP\n\n**⚠️ Always check for papilledema in isolated CN VI palsy!**\n\n**Common Causes:**\n1. Microvascular (most common in adults)\n2. **Elevated ICP** (check fundoscopy!)\n3. Trauma\n4. Tumor\n5. Infection/inflammation [3][8]","citation":[3,8],"next":"diplopia-cn6-workup","summary":"CN VI Palsy Overview — review key clinical information before proceeding"}'::jsonb
WHERE id = 'diplopia-cn6-start' AND tree_id = 'diplopia';

-- Node: diplopia-ino (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Internuclear Ophthalmoplegia (INO)","body":"**INO - Medial Longitudinal Fasciculus Lesion**\n\n**Anatomy:**\n• MLF connects CN VI nucleus to contralateral CN III nucleus\n• Coordinates conjugate horizontal gaze\n\n**Clinical Findings:**\n• **Impaired ADDUCTION** of ipsilateral eye\n• **Nystagmus of ABDUCTING** (contralateral) eye\n• Convergence usually preserved (different pathway)\n• Name INO by side with impaired adduction\n\n**Example - Left INO:**\n• Looking RIGHT: Left eye cannot adduct, right eye has nystagmus\n• Convergence: Both eyes can adduct\n\n**Etiology by Age:**\n\n| Age | Most Likely Cause | Laterality |\n|-----|-------------------|------------|\n| Young | **Multiple Sclerosis** | Often bilateral |\n| Older | **Stroke** | Usually unilateral |\n\n**Stats:**\n• ~33% MS, ~33% stroke\n• INO present in ~23% of MS patients\n• Most common ocular movement abnormality in MS [9][10]","citation":[9,10],"next":"diplopia-ino-workup","summary":"Internuclear Ophthalmoplegia (INO) — review key clinical information before proceeding"}'::jsonb
WHERE id = 'diplopia-ino' AND tree_id = 'diplopia';

-- Node: diplopia-mg (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Myasthenia Gravis","body":"**Myasthenia Gravis - Fluctuating Diplopia:**\n\n**Key Features:**\n• **Fluctuating** ptosis and diplopia\n• **Fatigable** weakness (worse with sustained use)\n• **Worse in evening** or with fatigue\n• >50% present with isolated ocular symptoms initially\n\n**Bedside Tests:**\n\n**Ice Pack Test:**\n1. Apply ice pack to closed eyelid for 2-5 minutes\n2. Positive: Ptosis improves ≥2mm\n3. **Sensitivity ~77%, Specificity ~98%** (no false-positives in myasthenic-diplopia study); sensitivity drops in complete or very mild ptosis — a negative test does NOT exclude MG\n4. Cold inhibits acetylcholinesterase\n\n**Sustained Upgaze Test:**\n• Have patient look up for 60 seconds\n• Positive: Ptosis worsens or develops\n\n**Confirmatory Testing:**\n• AChR antibodies: 50-70% sensitive in ocular MG\n• Single fiber EMG: ~95% sensitive\n• Anti-MuSK antibodies if AChR negative\n\n**⚠️ Red Flag - Myasthenic Crisis:**\n• Respiratory weakness (FVC <1L or <15 mL/kg)\n• Bulbar symptoms (dysphagia, dysarthria)\n• Requires ICU admission [12][13]","citation":[12,13],"next":"diplopia-mg-disposition","summary":"Myasthenia Gravis — review key clinical information before proceeding"}'::jsonb
WHERE id = 'diplopia-mg' AND tree_id = 'diplopia';

-- Node: fh-string-yank (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"String-Yank Technique","body":"**Highly effective, minimally traumatic, often requires no anesthesia.** [1,4,7]\n\n**CONTRAINDICATION:**\n• **Free-floating body parts** (earlobe, nose, lip)\n• Must have stable surface to press against\n\n**EQUIPMENT:**\n• 0-silk suture, fishing line, or umbilical tape (~18 inches)\n• Eye protection for all personnel\n\n**TECHNIQUE:**\n1. Wrap string around bend of hook at midpoint\n2. Wind string around index finger for secure grip\n3. Stabilize skin surface (press against table/flat surface)\n4. **Apply firm downward pressure on hook shank** (to disengage barb)\n5. While maintaining shank pressure, **jerk string parallel to shank** in one quick motion\n6. **WARNING:** Hook will fly — ensure clear trajectory\n\n**SUCCESS RATE:** 65-90%\n\n**ADVANTAGES:**\n• Often no anesthesia needed\n• No new wound created\n• Can be done in field\n• Least painful technique","citation":[1,4,7],"next":"fh-post-removal","summary":"Wrap string at bend; press shank down; jerk parallel to shank; NOT for earlobes; 65-90% success"}'::jsonb
WHERE id = 'fh-string-yank' AND tree_id = 'fishhook-removal';

-- Node: fh-advance-cut (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Advance-and-Cut Technique","body":"**Almost always successful, even for large hooks. Best when barb is near skin surface.** [1,5,6]\n\n**INDICATIONS:**\n• Large hooks\n• Barb visible near skin surface\n• String-yank failed or contraindicated\n• Multiple-barbed hooks\n\n**ANESTHESIA:** Always required — local infiltration at exit point\n\n**TECHNIQUE FOR SINGLE-BARBED HOOKS:**\n1. Anesthetize skin where barb will exit\n2. Grasp shank with needle driver/hemostat\n3. Advance hook forward through tissue until barb exits skin\n4. Cut barb off with wire cutters\n5. Back remaining hook out through entry wound\n\n**TECHNIQUE FOR TREBLE/MULTIPLE HOOKS:**\n1. Advance hook until barb exits\n2. Cut shank at entry point (not the barb)\n3. Pull entire hook through in direction of advancement\n4. Avoids backing barb through tissue\n\n**SUCCESS RATE:** >95%\n\n**DISADVANTAGE:** Creates second wound (exit point)","citation":[1,5,6],"next":"fh-post-removal","summary":"Push through until barb exits; cut barb; back out remainder; >95% success; creates second wound"}'::jsonb
WHERE id = 'fh-advance-cut' AND tree_id = 'fishhook-removal';

-- Node: fh-needle-cover (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Needle-Cover Technique","body":"**More technically difficult but useful for sensitive areas where advance-and-cut is undesirable.** [1,5,7]\n\n**INDICATIONS:**\n• Face, ear, nose (where new wound undesirable)\n• Large hooks with prominent barbs\n• Single-barbed hooks only\n\n**EQUIPMENT:**\n• 18-gauge needle (or larger for big hooks)\n• Local anesthesia required\n\n**TECHNIQUE:**\n1. Anesthetize thoroughly around hook\n2. Insert 18G needle along entry tract, **bevel facing hook curve**\n3. Advance needle to cover the barb\n4. Once barb is sheathed, advance hook slightly to engage barb in needle lumen\n5. Back out hook and needle together as a unit\n6. Rotate/twist to help engage barb in needle\n\n**SUCCESS RATE:** 60-70%\n\n**CHALLENGES:**\n• Requires dexterity\n• Difficult to engage barb blind\n• Works best with superficially embedded hooks\n\n**MODIFICATION:**\nSome authors use #11 scalpel blade to create small nick for needle entry","citation":[1,5,7],"next":"fh-post-removal","summary":"Insert 18G needle to cover barb; back out together; technically difficult; 60-70% success"}'::jsonb
WHERE id = 'fh-needle-cover' AND tree_id = 'fishhook-removal';

-- Node: iih-onsd-technique (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"ONSD Measurement Technique","body":"**Equipment:**\n• High-frequency linear probe (7.5-12 MHz)\n• Tegaderm over closed eye (optional)\n• Generous ultrasound gel\n\n**Technique — \"Remember 3×5\":**\n\n1. Patient supine, eyes closed, looking straight ahead\n2. Place probe gently on closed eyelid (transverse)\n3. Identify optic nerve as hypoechoic stripe behind globe\n4. Measure **3 mm posterior** to the globe\n5. Measure inner edge to inner edge of sheath\n6. Repeat in **both eyes**, take **average**\n\n**Interpretation:**\n\n| ONSD | Interpretation |\n|------|----------------|\n| **<5 mm** | Normal |\n| **5-6 mm** | Indeterminate — correlate clinically |\n| **>6 mm** | Elevated ICP (>20 mmHg) |\n\n**Diagnostic Accuracy (ONSD >5 mm):**\n• Sensitivity: 88-100%\n• Specificity: 63-95%\n\n⚠️ **Measure both eyes** — unilateral findings may be artifact","citation":[5,6,7],"next":"iih-onsd-result","summary":"ONSD technique: 3mm behind globe, measure inner to inner. <5mm normal, 5-6mm indeterminate, >6mm elevated ICP. Check both eyes.","skippable":true}'::jsonb
WHERE id = 'iih-onsd-technique' AND tree_id = 'iih';

-- Node: misfits-cah (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Congenital Adrenal Hyperplasia (CAH)","body":"**CONGENITAL ADRENAL HYPERPLASIA - ADRENAL CRISIS**\n\n21-hydroxylase deficiency (most common). Cannot make cortisol or aldosterone.\n\n**PRESENTATION**\n• Typically presents at 1-2 weeks of life\n• Lethargy, poor feeding, vomiting\n• Dehydration, shock\n• **Classic labs:** Hyponatremia, hyperkalemia, hypoglycemia\n• Hyperpigmentation (ACTH effect)\n• **Ambiguous genitalia in females** (virilization)\n\n**CLASSIC TRIAD:**\n1. Hyponatremia (salt-wasting)\n2. Hyperkalemia\n3. Hypoglycemia\n\n**LAB CONFIRMATION:**\n• 17-hydroxyprogesterone (elevated)\n• Cortisol (low)\n• ACTH (elevated)\n\n**EMERGENCY TREATMENT:**\n\n**1. FLUID RESUSCITATION**\nNS 20 mL/kg boluses for shock\n\n**2. DEXTROSE**\nD10W or D10NS for hypoglycemia\n\n**3. STRESS-DOSE STEROIDS**\n[Hydrocortisone](#/drug/hydrocortisone) 25 mg IV (neonates) or 2 mg/kg\n• Life-saving in adrenal crisis\n• Give immediately if CAH suspected\n\n**4. TREAT HYPERKALEMIA**\nIf K >6.5 or ECG changes: calcium, insulin/glucose, kayexalate","citation":[1,7],"recommendation":"CAH crisis: NS boluses, D10 for hypoglycemia, Hydrocortisone 25 mg IV immediately. Check 17-OHP to confirm.","treatment":{"firstLine":{"drug":"Hydrocortisone","dose":"25 mg (neonate) or 2 mg/kg","route":"IV","frequency":"Once, then q6-8h","duration":"Until endocrine guidance","notes":"Stress-dose steroids are life-saving. Do not delay for lab confirmation."},"monitoring":"Glucose, Na, K. Repeat BMP in 2-4 hours. Watch for rebound hypokalemia."},"confidence":"definitive","calculatorLinks":[{"id":"peds-dose","label":"Peds Dose Calculator"}],"safetyLevel":"critical"}'::jsonb
WHERE id = 'misfits-cah' AND tree_id = 'misfits-peds';

-- Node: misfits-hsv (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"HSV Encephalitis","body":"**NEONATAL HSV - CRITICAL DIAGNOSIS**\n\nHerpes simplex virus can cause devastating encephalitis in neonates. Mortality approaches 80% if untreated.\n\n**RISK FACTORS:**\n• Maternal genital HSV (especially primary outbreak)\n• Vaginal delivery with active lesions\n• Prolonged rupture of membranes\n\n**THREE PATTERNS:**\n1. **SEM (Skin, Eye, Mouth):** Vesicles, conjunctivitis - best prognosis\n2. **CNS disease:** Seizures, lethargy, CSF pleocytosis\n3. **Disseminated:** Multi-organ (liver, lungs, DIC) - worst prognosis\n\n**CLINICAL CLUES:**\n• Vesicular rash (may be absent in 20-40%)\n• Seizures, lethargy\n• Fever or hypothermia\n• CSF pleocytosis\n• Elevated LFTs, DIC\n• Respiratory failure\n\n**WORKUP:**\n• HSV PCR - blood (plasma)\n• HSV PCR - CSF\n• Surface cultures (conjunctiva, mouth, nasopharynx, rectum)\n• Vesicle viral culture/PCR if lesions present\n• AST, ALT, coagulation studies\n\n**TREATMENT:**\n[Acyclovir](#/drug/acyclovir) 20 mg/kg IV q8h\n• Start IMMEDIATELY if HSV suspected\n• Do NOT wait for PCR results\n• Duration: SEM 14 days; CNS/disseminated 21 days\n• Ensure adequate hydration (crystalline nephropathy)","citation":[1,11,12],"recommendation":"HSV: Acyclovir 20 mg/kg IV q8h immediately if suspected. Do NOT wait for PCR. SEM 14d, CNS/disseminated 21d.","treatment":{"firstLine":{"drug":"Acyclovir","dose":"20 mg/kg","route":"IV","frequency":"q8h","duration":"SEM: 14 days; CNS/disseminated: 21 days","notes":"Start immediately if HSV suspected. Adequate hydration prevents crystalline nephropathy."},"monitoring":"HSV PCR results. LFTs, renal function. Neurologic status. Repeat LP at end of treatment for CNS disease."},"confidence":"definitive","calculatorLinks":[{"id":"peds-dose","label":"Peds Dose Calculator"}],"safetyLevel":"critical"}'::jsonb
WHERE id = 'misfits-hsv' AND tree_id = 'misfits-peds';

-- Node: misfits-nec (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Necrotizing Enterocolitis (NEC)","body":"**NECROTIZING ENTEROCOLITIS (NEC)**\n\nIschemic necrosis of intestinal mucosa. Most common GI emergency in premature infants.\n\n**RISK FACTORS:**\n• Prematurity (primary risk factor)\n• Formula feeding (breast milk protective)\n• Perinatal asphyxia\n• PDA, CHD\n• Polycythemia\n\n**PRESENTATION:**\n• Abdominal distension\n• Feeding intolerance, vomiting\n• Bloody stools (heme-positive)\n• Lethargy, temperature instability\n• Apnea, bradycardia\n\n**IMAGING:**\n• **Pneumatosis intestinalis** (air in bowel wall) - pathognomonic\n• **Portal venous gas** - severe disease\n• **Pneumoperitoneum** - perforation, surgical emergency\n• Dilated bowel loops, thickened walls\n\n**MANAGEMENT:**\n1. NPO - bowel rest\n2. NGT decompression\n3. IV fluids and TPN\n4. Broad-spectrum antibiotics:\n   - [Ampicillin](#/drug/ampicillin) + [Gentamicin](#/drug/gentamicin) + [Metronidazole](#/drug/metronidazole)\n   - Or Vancomycin + Piperacillin-tazobactam\n5. Serial abdominal exams\n6. Surgical consult\n\n**SURGICAL INDICATIONS:**\n• Pneumoperitoneum (free air)\n• Fixed dilated loop\n• Clinical deterioration despite medical management","citation":[1,14,15],"recommendation":"NEC: NPO, NGT, IV fluids, broad-spectrum antibiotics (Amp/Gent/Flagyl). Surgical consult for pneumoperitoneum or deterioration.","treatment":{"firstLine":{"drug":"Ampicillin + Gentamicin + Metronidazole","dose":"Amp 50 mg/kg, Gent 4 mg/kg, Metro 15 mg/kg","route":"IV","frequency":"Amp q8h, Gent q24h, Metro q12h","duration":"10-14 days if confirmed NEC","notes":"Alternative: Vancomycin + Piperacillin-tazobactam. Surgical consult for all cases."},"monitoring":"Serial abdominal exams q4-6h. Serial abdominal XR. CBC, platelets, lactate."},"confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'misfits-nec' AND tree_id = 'misfits-peds';

-- Node: misfits-volvulus (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Malrotation with Midgut Volvulus","body":"**MALROTATION WITH MIDGUT VOLVULUS - SURGICAL EMERGENCY**\n\n**BILIOUS VOMITING IN A NEONATE IS VOLVULUS UNTIL PROVEN OTHERWISE**\n\nMalrotation (abnormal intestinal rotation during development) allows midgut to twist on SMA pedicle, causing ischemia.\n\n**PRESENTATION:**\n• **Bilious (green) vomiting** - hallmark\n• Abdominal distension (may be minimal early)\n• Abdominal pain (infant draws up legs, irritable)\n• Bloody stools (late sign - mucosal necrosis)\n• Shock, acidosis (late)\n\n**CRITICAL POINT:**\nVolvulus can progress from viable to necrotic bowel in HOURS. Do not delay.\n\n**IMAGING:**\n• **Upper GI series** - gold standard\n  - \"Corkscrew\" or \"bird''s beak\" sign\n  - Duodenal obstruction\n  - Abnormal DJ position\n• **XR** - may show double bubble (with distal gas if incomplete), or dilated stomach\n• **US** - whirlpool sign of twisted mesentery\n\n**MANAGEMENT:**\n1. NPO, NGT decompression\n2. Aggressive fluid resuscitation\n3. **EMERGENT surgical consult**\n4. Broad-spectrum antibiotics\n5. Prepare for OR\n\n**DO NOT DELAY:**\n• Upper GI should be done emergently\n• If high suspicion and patient unstable, may go directly to OR","citation":[1,14,16],"recommendation":"BILIOUS VOMITING = VOLVULUS until proven otherwise. Emergent UGI series. Surgical consult immediately. NPO, NGT, fluids.","treatment":{"firstLine":{"drug":"Fluid resuscitation + Antibiotics","dose":"NS 20 mL/kg boluses; Ampicillin + Gentamicin + Metronidazole","route":"IV","frequency":"Boluses PRN; Antibiotics per protocol","duration":"Until surgical repair","notes":"SURGICAL EMERGENCY. Do not delay for imaging if unstable."},"monitoring":"Lactate, VBG. Abdominal exam. Urine output. Prepare for OR."},"confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'misfits-volvulus' AND tree_id = 'misfits-peds';

-- Node: opocus-technique (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Probe Selection & Technique","body":"**Equipment:**\n• **High-frequency linear probe** (7.5-15 MHz)\n• Higher frequency = better resolution for superficial structures\n• Acoustic standoff: thick layer of gel or Tegaderm over closed lid\n\n**Patient Position:**\n• Supine with eyes closed\n• Ask patient to look straight ahead (reduces movement artifact)\n• May ask to look in different directions to assess detachments\n\n**Scanning Technique:**\n\n| Plane | Orientation | Purpose |\n|-------|-------------|--------|\n| **Transverse** | Marker temporal | Standard view, assess globe |\n| **Longitudinal** | Marker superior | Sagittal view, ONSD measurement |\n\n**Probe Pressure:**\n• **MINIMAL pressure** — rest probe on gel, not on lid\n• Excessive pressure can compress the globe and alter measurements\n• If trauma: use extra gel as standoff, absolutely no pressure\n\n**Depth:** Start at 4-5 cm to see entire globe and orbit. [1][2][3]","citation":[1,2,3],"next":"opocus-systematic","summary":"High-frequency linear probe 7.5-15 MHz, copious gel standoff, MINIMAL pressure, transverse (marker temporal) and longitudinal planes, depth 4-5cm"}'::jsonb
WHERE id = 'opocus-technique' AND tree_id = 'ocular-pocus';

-- Node: opocus-normal (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Normal Ocular Anatomy","body":"**Normal Sonographic Appearance:**\n\n**Anterior Structures (superficial to deep):**\n• **Eyelid:** Thin hyperechoic line\n• **Cornea:** Thin curved hyperechoic line\n• **Anterior Chamber:** Anechoic space between cornea and iris\n• **Iris:** Echogenic structure surrounding pupil\n• **Lens:** Biconvex, hypoechoic with hyperechoic capsule\n\n**Globe:**\n• **Vitreous:** **Completely anechoic** (dark/black)\n• Any echoes in vitreous = abnormal (hemorrhage, detachment, debris)\n• Globe diameter: ~24 mm (adult)\n\n**Posterior Structures:**\n• **Retina:** Normally adherent to posterior globe wall — NOT visible separately\n• **Optic Nerve:** Hypoechoic band extending posteriorly\n• **Optic Nerve Sheath:** Hyperechoic borders around nerve\n\n**Key Normal Finding:** Vitreous should be completely anechoic. Any echogenicity is abnormal. [1][3][4]","citation":[1,3,4],"next":"opocus-pathology-decision","summary":"Normal: anechoic vitreous, biconvex lens, retina adherent to wall — any echogenicity in vitreous is abnormal","skippable":true}'::jsonb
WHERE id = 'opocus-normal' AND tree_id = 'ocular-pocus';

-- Node: opocus-rd-findings (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Retinal Detachment Findings","body":"**Retinal Detachment (RD) — SURGICAL EMERGENCY:**\n\n**Classic Appearance:**\n• **V-shaped or tent-shaped** membrane in vitreous\n• **Tethered at optic disc** — does not float freely\n• **Thick, hyperechoic** compared to vitreous\n• May see undulating movement but anchored posteriorly\n\n**Types:**\n\n| Type | Description |\n|------|------------|\n| **Partial RD** | V-shape or fold, attached to disc |\n| **Total RD** | Complete \"funnel\" or \"morning glory\" appearance |\n| **Macula-on** | Macula still attached — EMERGENT (preserve central vision) |\n| **Macula-off** | Macula detached — urgent but timing less critical |\n\n**Key Feature:** The retina CANNOT move past the optic disc — it is anatomically tethered.\n\n**Dynamic Test:**\n• Have patient look left/right rapidly\n• RD: Membrane moves but remains attached to disc\n• Movement is restricted, \"leashed\"\n\n**Sensitivity:** 97-100% | **Specificity:** 83-100% [1][2][5][6]","citation":[1,2,5,6],"next":"opocus-pvd-findings","summary":"RD: V-shaped/tent-shaped, tethered at optic disc, thick hyperechoic, restricted movement — macula-on = emergent surgery within 24h","safetyLevel":"critical"}'::jsonb
WHERE id = 'opocus-rd-findings' AND tree_id = 'ocular-pocus';

-- Node: opocus-pvd-findings (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Posterior Vitreous Detachment","body":"**Posterior Vitreous Detachment (PVD) — Usually Benign:**\n\n**What Is PVD?**\n• Separation of vitreous gel from retina\n• Normal aging process (50% by age 50, 75% by age 75)\n• Symptomatic: floaters, flashes\n• Usually benign, but can be associated with RD in 10-15%\n\n**Sonographic Appearance:**\n• **Thin, undulating membrane** in posterior vitreous\n• **NOT tethered to optic disc** — floats freely\n• **\"Seaweed in water\"** or \"kelp\" motion\n• Less hyperechoic than RD (thinner membrane)\n\n**Dynamic Test (Critical):**\n• Have patient look side-to-side rapidly, then stop\n• PVD: **Membrane continues to undulate after eye stops moving**\n• RD: Membrane stops when eye stops (tethered)\n\n**Clinical Pearl:**\n\"If it floats freely like a jellyfish, it''s PVD. If it''s leashed to the disc like a dog on a chain, it''s RD.\"\n\n**Still Needs Outpatient F/U:** 10-15% of PVD have concurrent RD, and PVD increases RD risk. [1][3][5]","citation":[1,3,5],"next":"opocus-rd-pvd-comparison","summary":"PVD: thin undulating membrane NOT tethered to disc, \"seaweed in water\" motion, continues moving after eye stops — usually benign but 10-15% have concurrent RD"}'::jsonb
WHERE id = 'opocus-pvd-findings' AND tree_id = 'ocular-pocus';

-- Node: opocus-rd-pvd-comparison (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"RD vs PVD: Side-by-Side","body":"**Key Differentiating Features:**\n\n| Feature | Retinal Detachment | PVD |\n|---------|-------------------|-----|\n| **Shape** | V-shape / tent / funnel | Undulating membrane |\n| **Attachment** | **Tethered to disc** | Floats freely |\n| **Movement** | Restricted, \"leashed\" | Free, \"seaweed\" |\n| **Thickness** | Thicker, more echogenic | Thin, less echogenic |\n| **After-movement** | Stops with eye | **Continues after eye stops** |\n| **Urgency** | **SURGICAL EMERGENCY** | Outpatient follow-up |\n\n**Clinical Decision:**\n\n| Finding | Action |\n|---------|---------|\n| **Clear RD** | Emergent ophthalmology consult |\n| **Clear PVD only** | Outpatient ophthalmology 24-48h |\n| **Uncertain** | Treat as RD — emergent consult |\n| **PVD + vision loss** | Urgent consult — rule out concurrent RD |\n\n**When in Doubt:** Call ophthalmology. The consequences of missing RD far outweigh unnecessary consultation. [1][2][5][6]","citation":[1,2,5,6],"next":"opocus-vitreous-hemorrhage","calculatorLinks":[{"id":"opocus-rd-vs-pvd","label":"RD vs PVD"}],"summary":"Key: RD tethered to disc (leashed), PVD floats freely (jellyfish); uncertain = treat as RD and consult ophthalmology","safetyLevel":"warning"}'::jsonb
WHERE id = 'opocus-rd-pvd-comparison' AND tree_id = 'ocular-pocus';

-- Node: opocus-vitreous-hemorrhage (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Vitreous Hemorrhage","body":"**Vitreous Hemorrhage — Blood in the Vitreous Cavity:**\n\n**Causes:**\n• Diabetic retinopathy (most common)\n• Trauma\n• Retinal tear with vessel disruption\n• Posterior vitreous detachment\n• Age-related macular degeneration\n• Retinal vein occlusion\n\n**Sonographic Appearance:**\n• **Diffuse echogenic particles** throughout vitreous\n• \"Snowstorm\" or \"starry sky\" pattern\n• **Swirling motion** with eye movement (\"washing machine sign\")\n• May layer inferiorly if large/dense\n• Obscures view of posterior structures\n\n**Grading:**\n\n| Grade | Description |\n|-------|------------|\n| Mild | Scattered echoes, can see retina |\n| Moderate | Dense echoes, partial retinal view |\n| Severe | Complete obscuration of posterior segment |\n\n**Clinical Importance:**\n• Cannot see retina = cannot rule out RD\n• Dense VH + acute vision loss → ophthalmology consult\n• Need to rule out concurrent retinal tear/detachment [1][3][5]","citation":[1,3,5],"next":"opocus-other-pathology","summary":"VH: diffuse echogenic particles \"snowstorm\" pattern, swirling with eye movement — cannot see retina = cannot rule out RD, consult ophthalmology"}'::jsonb
WHERE id = 'opocus-vitreous-hemorrhage' AND tree_id = 'ocular-pocus';

-- Node: opocus-other-pathology (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Other Ocular Pathology","body":"**Additional Findings to Recognize:**\n\n**Lens Dislocation:**\n• Lens not in normal biconvex position\n• May be posterior (in vitreous), anterior, or subluxed\n• Associated with Marfan syndrome, homocystinuria, trauma\n• Can cause acute glaucoma or visual axis obstruction\n\n**Intraocular Foreign Body (IOFB):**\n• Hyperechoic structure with posterior shadowing (metal)\n• May see reverberation artifact (glass, metal)\n• Document location, size, and any associated globe injury\n• Do NOT use MRI if metallic FB suspected\n\n**Globe Rupture Signs:**\n• Irregular globe contour\n• Decreased globe volume\n• Intraocular air (bright echoes)\n• Vitreous hemorrhage (often seen)\n• **If suspected — STOP scanning, protect eye, consult**\n\n**Choroidal Detachment:**\n• Thick, smooth dome-shaped elevations\n• Do NOT extend to optic disc (vs. RD)\n• May be serous (post-surgery) or hemorrhagic (trauma) [1][2][7]","citation":[1,2,7],"next":"opocus-onsd-indication","summary":"Additional findings: lens dislocation (Marfan, trauma), IOFB (hyperechoic with shadow, no MRI if metallic), choroidal detachment (dome-shaped, not to disc)"}'::jsonb
WHERE id = 'opocus-other-pathology' AND tree_id = 'ocular-pocus';

-- Node: opocus-onsd-measure (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"ONSD Measurement Technique","body":"**Step-by-Step ONSD Measurement:**\n\n**1. Position:**\n• Patient supine, eyes closed, looking straight ahead\n• Ultrasound depth: 4 cm\n\n**2. Obtain View:**\n• Longitudinal/sagittal plane (marker superior)\n• Identify optic nerve as hypoechoic band extending posteriorly from globe\n• Optic nerve sheath = hyperechoic borders surrounding nerve\n\n**3. Measure:**\n• **3 mm posterior to the globe** (this is critical)\n• Measure **outer edge to outer edge** of sheath (OD to OD)\n• Calipers perpendicular to long axis of nerve\n\n**4. Bilateral Measurements:**\n• Measure BOTH eyes\n• Take average of both\n• Or report the higher value\n\n**Threshold Values:**\n\n| Population | ONSD Threshold |\n|------------|---------------|\n| **Adult** | **>5.0 mm** = elevated ICP |\n| **Child (1-15 y)** | **>4.5 mm** |\n| **Infant (<1 y)** | **>4.0 mm** |\n\n**Sensitivity:** 90% | **Specificity:** 85% for ICP >20 mmHg [1][4][8][9]","citation":[1,4,8,9],"next":"opocus-onsd-interpret","calculatorLinks":[{"id":"opocus-onsd-calc","label":"ONSD Calculator"}],"summary":"Measure 3mm behind globe, outer edge to outer edge, bilateral average — adult >5.0mm, child >4.5mm, infant >4.0mm = elevated ICP","safetyLevel":"critical"}'::jsonb
WHERE id = 'opocus-onsd-measure' AND tree_id = 'ocular-pocus';

-- Node: opocus-trauma-findings (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Traumatic Findings","body":"**Post-Trauma Ocular Pathology:**\n\n**Hyphema:**\n• Blood in anterior chamber\n• Layering red cells with fluid level\n• May completely fill AC (8-ball hyphema)\n• Risk: secondary hemorrhage, glaucoma\n\n**Lens Dislocation:**\n• Posterior dislocation — lens in vitreous\n• Anterior dislocation — lens in AC (can cause pupil block)\n• Subluxation — partial displacement\n• Associated with zonular damage\n\n**Intraocular Foreign Body:**\n• Hyperechoic with posterior acoustic shadow (metal)\n• Reverberation artifact (glass, metal)\n• Document: location, size, trajectory\n• CT orbit if metallic (no MRI)\n\n**Traumatic Retinal Detachment:**\n• Same appearance as spontaneous RD\n• V-shaped, tethered to disc\n• May have associated VH\n\n**Globe Rupture Findings (if you see this — already scanned too much):**\n• Irregular contour\n• Collapsed globe\n• Loss of normal spherical shape [1][2][7]","citation":[1,2,7],"next":"opocus-crao","summary":"Traumatic findings: hyphema (blood in AC), lens dislocation, IOFB (CT if metallic, no MRI), traumatic RD — globe rupture on US = already scanned too much"}'::jsonb
WHERE id = 'opocus-trauma-findings' AND tree_id = 'ocular-pocus';

-- Node: pm-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Pacemaker Emergencies: Overview","body":"**Device emergencies are common and manageable with systematic approach.**\n\n**Key Questions:**\n1. What type of device? (Pacemaker vs ICD vs CRT)\n2. Is there a malfunction? (ECG analysis)\n3. Is the patient stable or unstable?\n4. When to use a magnet?\n\n**Device Types:**\n\n| Device | Function |\n|--------|----------|\n| **Pacemaker** | Prevents bradycardia only |\n| **ICD** | Detects/treats VT/VF (shocks) + may pace |\n| **CRT-P** | Biventricular pacing for heart failure |\n| **CRT-D** | CRT + ICD (shocks + pacing) |\n\n**Generator Location:**\n• Usually left pectoral (subclavicular)\n• Occasionally right-sided or abdominal\n• Look for scar, palpate device\n\n**Device ID Card:** Patient should carry - shows manufacturer, model, leads [1][2]","citation":[1,2],"next":"pm-nbg-code","calculatorLinks":[{"id":"pm-device-id","label":"Device ID"}],"summary":"Systematic approach: identify device type (pacemaker/ICD/CRT), assess for malfunction on ECG, determine stability, know when to use magnet","skippable":true}'::jsonb
WHERE id = 'pm-start' AND tree_id = 'pacemaker';

-- Node: pm-nbg-code (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"NBG Pacemaker Code","body":"**The NBG/NASPE code describes pacemaker function.**\n\n**5-Position Code:**\n\n| Position | Letter | Meaning |\n|----------|--------|--------|\n| **I** | A/V/D/O | Chamber **Paced** |\n| **II** | A/V/D/O | Chamber **Sensed** |\n| **III** | O/I/T/D | **Response** to sensing |\n| **IV** | O/R | **Rate** modulation |\n| **V** | O/A/V/D | **Multisite** pacing |\n\n**Letters:**\n• **A** = Atrium | **V** = Ventricle | **D** = Dual (both)\n• **O** = None | **I** = Inhibited | **T** = Triggered\n• **R** = Rate-responsive\n\n**Common Modes:**\n\n| Mode | Description | Use |\n|------|-------------|-----|\n| **VVI** | V pace, V sense, Inhibited | Basic single-chamber |\n| **AAI** | A pace, A sense, Inhibited | Sinus node dysfunction, intact AV |\n| **DDD** | Dual pace, Dual sense, Dual response | Most versatile |\n| **VOO/DOO** | Asynchronous (no sensing) | Magnet mode |\n\n[NBG Decoder Calculator](#/calculator/pm-nbg-decoder) [1][3]","citation":[1,3],"next":"pm-indications","calculatorLinks":[{"id":"pm-nbg-decoder","label":"NBG Decoder"}],"summary":"NBG code: I=paced, II=sensed, III=response; common modes VVI (basic), DDD (most versatile), VOO/DOO (asynchronous magnet mode)","skippable":true}'::jsonb
WHERE id = 'pm-nbg-code' AND tree_id = 'pacemaker';

-- Node: pm-fail-pace (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Failure to Pace","body":"**No pacing spikes when heart rate is below programmed lower rate.**\n\n**Causes:**\n• **Lead fracture** - most common hardware cause\n• **Lead dislodgment**\n• **Battery depletion** (check magnet rate)\n• **Oversensing** - device thinks heart is beating\n• **Generator failure**\n• **Loose set screw** (connection at header)\n\n**Workup:**\n1. **Chest X-ray** - look for lead fracture, dislodgment\n2. **Apply magnet** - will it pace in asynchronous mode?\n3. **Check magnet rate** - low rate = depleted battery\n4. **Device interrogation** - definitive\n\n**If Magnet Restores Pacing:**\n→ Likely oversensing (magnet bypasses sensing)\n→ Keep magnet on, arrange interrogation\n\n**If Magnet Does NOT Restore Pacing:**\n→ Lead fracture, severe battery depletion, or generator failure\n→ Transcutaneous pacing as bridge [2][5][6]","citation":[2,5,6],"next":"pm-malfunction-management","summary":"Failure to pace: lead fracture, dislodgment, battery depletion, oversensing — apply magnet (if restores pacing = oversensing), check CXR for lead issues"}'::jsonb
WHERE id = 'pm-fail-pace' AND tree_id = 'pacemaker';

-- Node: pm-fail-capture (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Failure to Capture","body":"**⚠️ Pacing spikes present WITHOUT subsequent P wave or QRS. ⚠️**\n\n**Causes:**\n\n**Lead-Related:**\n• Lead dislodgment (most common early post-implant)\n• Lead fracture\n• Lead perforation\n\n**Threshold-Related:**\n• **Hyperkalemia** - K+ >7 mEq/L classic cause\n• Acidosis\n• Hypoxia\n• Ischemia\n• Exit block (fibrosis at lead tip - late)\n\n**Medication-Related:**\n• Flecainide, propafenone\n• Class I antiarrhythmics\n\n**Device:**\n• Battery depletion\n• Output programmed too low\n\n**⚠️ ALWAYS CHECK POTASSIUM ⚠️**\n\n**Acute Management:**\n1. **Check K+** - treat hyperkalemia aggressively\n2. **Increase output** (if able to reprogram)\n3. **Transcutaneous pacing** if unstable\n4. **Magnet** may help (higher output in some devices) [2][5][6]","citation":[2,5,6],"next":"pm-malfunction-management","calculatorLinks":[{"id":"pm-capture-causes","label":"Capture Causes"}],"summary":"Failure to capture: ALWAYS CHECK POTASSIUM (K>7 classic cause), also acidosis/hypoxia/ischemia; treat hyperkalemia aggressively, TCP if unstable","safetyLevel":"critical"}'::jsonb
WHERE id = 'pm-fail-capture' AND tree_id = 'pacemaker';

-- Node: pm-undersensing (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Failure to Sense (Undersensing)","body":"**Pacing spikes occurring regardless of intrinsic rhythm.**\n\n**ECG Pattern:**\n• Pacing spikes falling during or after native QRS\n• Pacing that ignores intrinsic beats\n• \"Competition\" between device and native rhythm\n\n**⚠️ DANGER: May pace on T wave → R-on-T → VF ⚠️**\n\n**Causes:**\n• Sensitivity programmed too low\n• Lead dislodgment\n• Lead fracture\n• Inadequate intrinsic signal amplitude\n• Fibrosis at lead-tissue interface\n• New bundle branch block (changes signal)\n\n**Management:**\n1. **Apply magnet** - converts to asynchronous (will still pace, but at least consistent)\n2. **Reprogram sensitivity** (interrogation needed)\n3. If causing hemodynamic issues, may need lead revision\n\n**Note:** Magnet does NOT fix undersensing - it just makes pacing asynchronous. The danger is that the device IS pacing when it shouldn''t. [2][5]","citation":[2,5],"next":"pm-malfunction-management","summary":"Undersensing: paces regardless of intrinsic rhythm — DANGER of R-on-T triggering VF; magnet converts to asynchronous but does NOT fix the problem","safetyLevel":"critical"}'::jsonb
WHERE id = 'pm-undersensing' AND tree_id = 'pacemaker';

-- Node: pm-oversensing (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Oversensing","body":"**Device is inhibited by signals it mistakes for cardiac activity.**\n\n**ECG Pattern:**\n• Pauses without pacing when pacing should occur\n• Intermittent failure to pace\n• Often position-dependent or activity-related\n\n**What Is Being Oversensed?**\n• **Myopotentials** - skeletal muscle (pectoralis)\n• **T-wave sensing** - large T waves mistaken for QRS\n• **EMI** - electromagnetic interference\n• **Lead fracture noise** - random signals\n• **Cross-talk** - atrial spike sensed by ventricular lead\n\n**Clues:**\n• Symptoms with arm movement (myopotentials)\n• Near certain equipment (EMI)\n• Erratic sensing on interrogation (lead fracture)\n\n**Management:**\n1. **Apply magnet** - bypasses sensing, restores pacing\n2. Keep magnet in place until interrogation\n3. **Reprogram sensitivity** or **blanking periods**\n4. Lead repair if fractured\n\n**Magnet is the definitive treatment until reprogramming!** [2][5]","citation":[2,5],"next":"pm-malfunction-management","summary":"Oversensing: device inhibited by non-cardiac signals (myopotentials, T-waves, EMI, lead fracture noise) — magnet bypasses sensing and restores pacing"}'::jsonb
WHERE id = 'pm-oversensing' AND tree_id = 'pacemaker';

-- Node: pm-pmt (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Pacemaker-Mediated Tachycardia","body":"**PMT (Endless Loop Tachycardia) - DDD pacemakers only.**\n\n**Mechanism:**\n1. PVC or loss of atrial capture\n2. Retrograde conduction to atrium\n3. Atrial lead senses retrograde P wave\n4. Triggers ventricular pacing\n5. Ventricular pace conducts retrograde to atrium\n6. Cycle repeats → tachycardia at upper tracking rate\n\n**ECG Pattern:**\n• Regular tachycardia at or near **upper tracking rate** (usually 110-130 bpm)\n• Ventricular paced morphology\n• Often starts after a PVC\n\n**Treatment:**\n\n**1. Apply Magnet:**\n• Converts to asynchronous mode (VOO/DOO)\n• Breaks the loop immediately\n• Simple and effective\n\n**2. Adenosine:**\n• Blocks AV node, interrupts retrograde conduction\n• Works but less elegant than magnet\n\n**3. Reprogramming:**\n• Extend PVARP (post-ventricular atrial refractory period)\n• Enable PMT termination algorithms\n\n**Key:** Magnet is diagnostic AND therapeutic. [5][7]","citation":[5,7],"next":"pm-malfunction-management","summary":"PMT in DDD pacemakers: retrograde conduction creates endless loop at upper tracking rate — magnet breaks loop immediately, also try adenosine"}'::jsonb
WHERE id = 'pm-pmt' AND tree_id = 'pacemaker';

-- Node: pm-ecg-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Paced Rhythm ECG Basics","body":"**Identifying Pacing on ECG:**\n\n**Pacing Spikes:**\n• Vertical deflections, ~2 ms duration\n• Bipolar leads = smaller spikes (may be hard to see)\n• Unipolar leads = larger spikes\n• Not visible in all leads\n\n**Normal Paced QRS Morphology:**\n\n| Pacing Site | Pattern |\n|-------------|--------|\n| **RV apex** | LBBB + left axis deviation |\n| **RV septum** | LBBB, axis may be normal |\n| **LV (via CS)** | RBBB pattern |\n| **BiV (CRT)** | Narrower than RV alone, variable |\n\n**ST-T Changes:**\n• Should be **discordant** (opposite direction from QRS)\n• Concordant ST changes = concerning for ischemia\n\n**Types of Beats:**\n• **Fully paced** - spike + paced morphology\n• **Fusion** - native + paced activation together\n• **Pseudofusion** - spike on native QRS (no contribution)\n• **Native** - intrinsic beat [3][9]","citation":[3,9],"next":"pm-ecg-patterns","calculatorLinks":[{"id":"pm-ecg-pattern","label":"ECG Pattern"}],"summary":"Pacing spikes: vertical deflections; RV pacing = LBBB + LAD morphology; discordant ST-T normal; concordant ST changes = concerning for ischemia","skippable":true}'::jsonb
WHERE id = 'pm-ecg-start' AND tree_id = 'pacemaker';

-- Node: pm-ecg-patterns (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Pacing Patterns by Mode","body":"**Recognize Normal Pacing Patterns:**\n\n**AAI (Atrial Only):**\n• Atrial spike → P wave → native QRS\n• QRS is NARROW (native conduction)\n• Used when AV conduction intact\n\n**VVI (Ventricular Only):**\n• Ventricular spike → wide QRS\n• No relationship to P waves\n• AV dissociation may be present\n\n**DDD (Dual Chamber):**\n• Can show 4 patterns:\n  1. **A-sense, V-sense** - no spikes, native rhythm\n  2. **A-pace, V-sense** - atrial spike only\n  3. **A-sense, V-pace** - ventricular spike only\n  4. **A-pace, V-pace** - both spikes\n\n**Fusion Beats:**\n• Native activation + paced activation occur simultaneously\n• Intermediate morphology\n• Normal finding, not malfunction\n\n**Pseudofusion:**\n• Spike falls on native QRS but doesn''t contribute\n• QRS identical to native beat\n• Also normal [3][9]","citation":[3,9],"next":"pm-ecg-stemi","summary":"DDD shows 4 patterns (A-sense/V-sense to A-pace/V-pace); fusion beats = intermediate morphology (normal); pseudofusion = spike on native QRS (normal)","skippable":true}'::jsonb
WHERE id = 'pm-ecg-patterns' AND tree_id = 'pacemaker';

-- Node: pm-ecg-stemi (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"STEMI in Paced Rhythm","body":"**Modified Sgarbossa Criteria for STEMI with Paced Rhythm:**\n\n**Standard Sgarbossa (Original):**\n1. Concordant ST elevation ≥1 mm (5 points)\n2. Concordant ST depression ≥1 mm in V1-V3 (3 points)\n3. Discordant ST elevation ≥5 mm (2 points)\n\n**MODIFIED Criterion (Smith):**\n• Replace rule 3 with:\n• **ST elevation / S wave ratio ≥0.25**\n• (Proportionally excessive discordant STE)\n\n**Interpretation:**\n• ≥3 points = highly specific for STEMI\n• **ANY positive criterion** warrants cath lab activation\n\n**Key Point:**\n• Normal paced rhythm has **discordant** ST-T changes\n• **Concordant** ST changes are ALWAYS abnormal\n• Excessive discordant STE (>25% of S wave) is abnormal\n\n[Sgarbossa Calculator](#/calculator/pm-sgarbossa) [9][10]","citation":[9,10],"options":[{"label":"Return to Clinical Scenario","next":"pm-approach"}],"calculatorLinks":[{"id":"pm-sgarbossa","label":"Sgarbossa"}],"summary":"Modified Sgarbossa for paced STEMI: concordant STE ≥1mm, concordant STD V1-V3, or discordant STE ≥25% of S wave — ANY positive = activate cath lab","safetyLevel":"critical"}'::jsonb
WHERE id = 'pm-ecg-stemi' AND tree_id = 'pacemaker';

-- Node: pm-magnet-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Magnet Application Basics","body":"**⚠️ CRITICAL: Magnets affect PACEMAKERS and ICDs DIFFERENTLY! ⚠️**\n\n| Device | Magnet Effect |\n|--------|---------------|\n| **PACEMAKER** | Switches to **asynchronous pacing** (VOO/DOO) |\n| **ICD** | **Disables shock therapy** ONLY (pacing unchanged) |\n\n**Pacemaker + Magnet:**\n• Bypasses sensing → paces regardless of intrinsic rhythm\n• Paces at \"magnet rate\" (indicates battery status)\n• Useful for: oversensing, PMT, battery check\n\n**ICD + Magnet:**\n• Disables VT/VF detection and shock delivery\n• **Pacing function is UNCHANGED**\n• Useful for: inappropriate shocks, ICD storm, end of life\n• Tones often heard when applied (varies by manufacturer)\n\n**Magnet Placement:**\n• Directly over generator\n• Tape in place if needed to keep effect continuous\n\n**Remove Magnet:**\n• Device returns to programmed mode (usually) [5][11]","citation":[5,11],"next":"pm-magnet-rates","summary":"CRITICAL difference: magnet on PACEMAKER = asynchronous pacing (VOO/DOO); magnet on ICD = disables SHOCKS only (pacing unchanged)","safetyLevel":"critical"}'::jsonb
WHERE id = 'pm-magnet-start' AND tree_id = 'pacemaker';

-- Node: pm-shock-placement (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Pad Placement with Devices","body":"**Optimal Pad Placement:**\n\n**Preferred: Anterior-Posterior**\n• Avoids generator entirely\n• Current path away from leads\n• Best option when possible\n\n**Anterior-Lateral (Standard Position):**\n• Place pads **at least 8 cm (3 inches)** from generator\n• If device is left-sided:\n  - Move left (apex) pad more lateral or inferior\n  - Or use A-P position\n\n**Do NOT:**\n• Place pad directly over generator\n• Delay defibrillation to find generator\n\n**Energy Level:**\n• Use standard energy (biphasic 120-200J, monophasic 360J)\n• No need to reduce energy due to pacemaker\n\n**External Cardioversion:**\n• Same pad placement considerations\n• Synchronized cardioversion as usual [2][5][14]","citation":[2,5,14],"next":"pm-shock-post","summary":"A-P pad placement preferred (avoids generator); if anterior-lateral, pads ≥8cm from device; standard energy, no need to reduce for pacemaker"}'::jsonb
WHERE id = 'pm-shock-placement' AND tree_id = 'pacemaker';

-- Node: pm-tcp (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":7,"title":"Transcutaneous Pacing","body":"**TCP - First-Line for Emergent Pacing:**\n\n**Pad Placement:**\n• **Anterior-Posterior** preferred\n• Avoid pacemaker generator (≥8 cm away)\n• Good skin contact, remove excessive hair\n\n**Initial Settings:**\n\n| Parameter | Starting | Adjustment |\n|-----------|----------|------------|\n| **Rate** | 60-80 ppm | Adjust to hemodynamics |\n| **Output (mA)** | 30-50 mA | Increase by 5-10 mA until capture |\n\n**Finding Capture Threshold:**\n1. Start at 30-50 mA\n2. Increase until consistent capture\n3. Typical threshold: 50-100 mA\n4. Set output **1.25x threshold** (or 5-10 mA above)\n\n**Peri-Arrest/Arrest:**\n• Start at **maximum output** for rapid capture\n• Then titrate down\n\n**Confirming Capture:**\n• Wide QRS after each pacer spike\n• Palpable pulse (NOT just monitor artifact)\n• POCUS showing ventricular contraction\n• Improvement in hemodynamics [2][8]","citation":[2,8],"next":"pm-tcp-troubleshoot","calculatorLinks":[{"id":"pm-tcp-settings","label":"TCP Settings"}],"summary":"TCP: A-P pads ≥8cm from device, start 30-50mA increase by 5-10 until capture (typical 50-100mA), set 1.25x threshold; confirm with pulse not just monitor"}'::jsonb
WHERE id = 'pm-tcp' AND tree_id = 'pacemaker';

-- Node: pm-tvp (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":7,"title":"Transvenous Pacing","body":"**TVP - Definitive Temporary Pacing:**\n\n**Indications:**\n• TCP failure or poor capture\n• Prolonged pacing needed (>30 min)\n• Overdrive pacing for torsades\n• More reliable pacing required\n\n**Access Site (Preference Order):**\n1. **Right IJ** - straight path to RV, highest success\n2. **Left subclavian** - reserve for permanent site if possible\n3. **Femoral** - higher infection/thrombosis, patient can''t sit up\n\n**Equipment:**\n• 5-6 Fr introducer sheath\n• Balloon-tipped pacing catheter\n• Pacing generator\n\n**Procedure Overview:**\n1. Place sheath (ultrasound-guided)\n2. Advance catheter to ~20 cm\n3. Inflate balloon, float to RV\n4. Confirm position: ECG (injury current), POCUS, or fluoro\n5. Deflate balloon, test pacing\n\n**Settings:**\n• Rate: 60-80 ppm\n• Output: Determine threshold, set 2-3x threshold [2][8][15]","citation":[2,8,15],"next":"pm-pharm-bridge","summary":"TVP: right IJ preferred (straight path to RV), balloon-tipped catheter ~20cm, confirm with injury current/POCUS/fluoro; set output 2-3x threshold"}'::jsonb
WHERE id = 'pm-tvp' AND tree_id = 'pacemaker';

-- Node: pm-complications (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":7,"title":"Device Complications","body":"**Non-Malfunction Complications:**\n\n**Generator Pocket Infection:**\n• Erythema, warmth, discharge, erosion\n• Systemic signs (fever, bacteremia)\n• **Management:**\n  - Blood cultures x 3\n  - Superficial only (<30 days, no systemic signs): Trial oral abx\n  - True pocket infection: **Complete device extraction** + IV abx 10-14 days\n  - With endocarditis: Extraction + 4-6 weeks IV abx\n\n**Twiddler Syndrome:**\n• Patient manipulates generator in pocket\n• Leads coil around generator on X-ray\n• Causes malfunction, lead dislodgment\n• **Treatment:** Lead repositioning, secure generator to fascia\n\n**Lead Fracture:**\n• At clavicle-first rib junction (subclavian crush)\n• X-ray: Discontinuity or kinking of lead\n• Causes failure to capture, oversensing (noise)\n• **Treatment:** Lead replacement\n\n**Pacemaker Syndrome:**\n• Symptoms from loss of AV synchrony (VVI mode)\n• Fatigue, dyspnea, palpitations, hypotension\n• **Treatment:** Upgrade to DDD pacing [5][16][17]","citation":[5,16,17],"options":[{"label":"Return to Start","next":"pm-start"}],"summary":"Pocket infection: blood cultures, may need complete extraction + IV abx; Twiddler syndrome: leads coiled on CXR; lead fracture at subclavian crush site"}'::jsonb
WHERE id = 'pm-complications' AND tree_id = 'pacemaker';

-- Node: peds-fb-airway-imaging (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Airway FB — Imaging Strategy","body":"**Standard:** PA + lateral chest X-ray [4,7]\n\n**Findings (any/none):**\n- Radiopaque FB (rare — most are food/plastic)\n- Unilateral hyperinflation (ball-valve obstruction, expiratory air trapping)\n- Atelectasis distal to FB\n- Mediastinal shift\n- Consolidation (post-obstructive pneumonia)\n\n**Specialized views to detect air trapping** when standard CXR is normal but suspicion high:\n- **Inspiratory + expiratory CXR** (if child cooperates) — air trapping on expiration = ball valve\n- **Bilateral decubitus films** in younger child — dependent lung normally collapses; affected side stays inflated\n- **Fluoroscopy** if available — dynamic air trapping\n\n**CT chest** — high sensitivity but radiation + sedation in young child. Reserve for diagnostic uncertainty when bronchoscopy not immediately available. [4]\n\n**Bottom line:** Normal imaging in a child with witnessed choking event still warrants ENT/pulm consultation for diagnostic rigid bronchoscopy. [4,9]","citation":[4,7,9],"next":"peds-fb-airway-disposition","summary":"CXR may be normal; insp/exp or decubitus to detect air trapping; CT only if rigid bronch unavailable; high suspicion → bronch"}'::jsonb
WHERE id = 'peds-fb-airway-imaging' AND tree_id = 'peds-foreign-body';

-- Node: preg-trauma-positioning (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Left Uterine Displacement","body":"**CRITICAL after 20 weeks gestation:**\n\n**Why?**\n• Gravid uterus compresses IVC and aorta when supine\n• Can reduce cardiac output by **25-30%**\n• Causes supine hypotension syndrome\n\n---\n\n**METHODS:**\n\n**1. Manual displacement (preferred during CPR):**\n• Stand at patient''s right side\n• Place hands on right side of uterus\n• Push uterus to the LEFT and upward\n• Maintain throughout resuscitation\n\n**2. Left lateral tilt (if not in arrest):**\n• Tilt entire patient 15-30° to the left\n• Place wedge or rolled towels under right hip/back\n• If on backboard: tilt entire board\n\n---\n\n**⚠️ Do NOT compromise CPR quality for positioning**\nManual displacement allows supine CPR with effective compressions. [1][2][4]","citation":[1,2,4],"next":"preg-trauma-labs","summary":"Manual displacement: push uterus LEFT from patient''s right side. Or tilt 15-30° left.","safetyLevel":"critical"}'::jsonb
WHERE id = 'preg-trauma-positioning' AND tree_id = 'pregnancy-trauma';

-- Node: preg-trauma-rhyst (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Resuscitative Hysterotomy Technique","body":"**Formerly \"perimortem cesarean section\"**\n\n**INDICATION:** Maternal cardiac arrest with uterus ≥20 weeks (fundus at/above umbilicus) and no ROSC within 4 minutes.\n\n**GOAL:** Relieve aortocaval compression. Primary benefit is MATERNAL.\n\n---\n\n**EQUIPMENT:**\n• Scalpel (#10 blade)\n• Mayo scissors\n• Hemostats/clamps (for cord)\n• Bulb suction\n• Towels for packing\n• Neonatal resuscitation ready\n\n---\n\n**STEP-BY-STEP:**\n\n**1. Vertical midline incision** — umbilicus to pubic symphysis\n• Cut through skin, subcutaneous tissue, fascia\n• Bluntly dissect rectus muscles\n\n**2. Enter peritoneum** — identify uterus\n\n**3. Vertical uterine incision** — low segment to fundus\n• Avoid bladder (inferior)\n• If anterior placenta: cut through it\n\n**4. Insert fingers** — lift uterine wall away from fetus\n\n**5. Extend incision** with Mayo scissors\n\n**6. Deliver fetus head-first**\n• Clamp and cut cord\n• Hand off to neonatal team\n\n**7. Remove placenta** — pack uterus with towels\n\n**8. Continue maternal resuscitation**\n\n---\n\n**Maternal survival documented at 15 min. Neonatal survival at 30 min.** Do not give up early. [4][9][10]","citation":[4,9,10],"next":"preg-trauma-post-rhyst","summary":"Vertical midline skin + vertical uterus. Begin at 4 min, deliver by 5 min. Primary benefit is maternal.","safetyLevel":"critical"}'::jsonb
WHERE id = 'preg-trauma-rhyst' AND tree_id = 'pregnancy-trauma';

-- Node: vafei-procedure (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Procedure — Step by Step","body":"**THE TECHNIQUE:** [1]\n\n**STEP 1: VL INSERTION**\n• VL operator inserts blade, obtains laryngeal view\n• Maintains position with LEFT hand\n• Keeps suction ready in RIGHT hand\n• \"Sets the table\" for FE operator\n\n**STEP 2: FE INSERTION**\n• FE operator looks INTO patient''s mouth (direct vision)\n• Advances scope to tip of VL blade under direct view\n• Then looks at VL SCREEN to guide scope to cords\n\n**STEP 3: CORD PASSAGE**\n• Spray lidocaine on cords via FE channel (if awake)\n• Advance FE through vocal cords\n• Use VL screen OR FE screen (whichever view is better)\n• Continue until CARINA is visualized\n\n**STEP 4: TUBE DELIVERY**\n• FE operator holds scope steady\n• Assistant (or VL operator) railroads ETT over scope\n• Advance until ETT tip visible on FE screen\n• Position just proximal to carina\n\n**KEY PEARL:**\n\"The right speed is SLOWER than your instincts.\" [1]","citation":[1],"next":"vafei-railroad","summary":"VL obtains view → FE advances to blade tip → guides through cords on VL screen → carina → railroad ETT"}'::jsonb
WHERE id = 'vafei-procedure' AND tree_id = 'vafei';

-- Node: wct-pathognomonic (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Pathognomonic VT Features","body":"**If ANY of these present → confirms VT:**\n\n**AV dissociation:**\n• P waves at different rate than QRS\n• Classic finding, highly specific\n\n**Fusion beats:**\n• Hybrid complex (sinus + ventricular origin)\n• QRS morphology intermediate between normal and VT\n\n**Capture beats:**\n• Narrow QRS \"captured\" during wide complex tachycardia\n• Sinus impulse reaches ventricles between VT beats\n\n⚠️ **Absence of these does NOT rule out VT**","citation":[1,7],"next":"wct-other-features","summary":"Pathognomonic VT: AV dissociation, fusion beats, capture beats. If present = confirmed VT."}'::jsonb
WHERE id = 'wct-pathognomonic' AND tree_id = 'wide-complex-tachycardia';

-- Node: wct-brugada (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Brugada Algorithm","body":"**Step-by-step (stop if YES at any step = VT):**\n\n**Step 1:** Absence of RS complex in ALL precordial leads (V1-V6)?\n• All monophasic = VT\n\n**Step 2:** RS interval >100ms in any precordial lead?\n• Measure R onset to S nadir\n• >100ms = VT\n\n**Step 3:** AV dissociation present?\n• P waves at different rate = VT\n\n**Step 4:** Morphology criteria (V1 and V6):\n• **RBBB pattern:** Tall left rabbit ear in V1, or QS/rS in V6 = VT\n• **LBBB pattern:** R >30ms in V1, notched S descent, RS >70ms = VT\n\n**If all 4 steps NO → suggests SVT**","citation":[4,6,9],"next":"wct-brugada-result","summary":"Brugada: 4 steps — no RS in precordials, RS >100ms, AV dissociation, morphology criteria. Any YES = VT."}'::jsonb
WHERE id = 'wct-brugada' AND tree_id = 'wide-complex-tachycardia';

-- Node: wct-vereckei (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Vereckei aVR Algorithm","body":"**Analyze lead aVR only (faster than Brugada):**\n\n**Step 1:** Initial dominant R wave in aVR?\n• YES = VT\n\n**Step 2:** Initial r or q wave width >40ms?\n• YES = VT\n\n**Step 3:** Notching on initial downstroke of predominantly negative QRS?\n• YES = VT\n\n**Step 4:** Vi/Vt ratio ≤1?\n• Vi = vertical excursion in initial 40ms\n• Vt = vertical excursion in terminal 40ms\n• Ratio ≤1 = VT\n\n**If all 4 steps NO → suggests SVT**\n\n⏱️ Faster than Brugada (36 sec vs 105 sec median)","citation":[7],"next":"wct-vereckei-result","summary":"Vereckei: aVR only — initial R, initial r/q >40ms, notched downstroke, Vi/Vt ≤1. Any YES = VT."}'::jsonb
WHERE id = 'wct-vereckei' AND tree_id = 'wide-complex-tachycardia';

-- Node: wrist-colles (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":1,"title":"Colles Fracture Management","body":"**Classic Charnley Reduction Technique:**\n\n**Pre-Reduction:**\n• Procedural sedation\n• Consider hematoma block (10-15 mL lidocaine into fracture site)\n• Finger traps × 10 minutes (optional)\n\n**Reduction Steps:**\n1. Apply continuous longitudinal traction\n2. **Disimpact** fracture: exaggerate dorsal angulation (increase deformity)\n3. **Robert-Jones maneuver:** While maintaining traction, force distal fragment volarly (push volar with thumbs on dorsal fragment)\n4. Return wrist to neutral to slight extension (10-20°)\n5. Maintain traction while applying splint\n\n**Post-Reduction:**\n• Sugar tong splint (limits forearm rotation)\n• Post-reduction films (PA, lateral, oblique)\n• Reassess neurovascular status\n\n**Acceptable Reduction:**\n• Radial shortening <3mm\n• Dorsal tilt <10° (or <5° for intra-articular)\n• Intra-articular step-off <2mm\n\n**📞 Urgent ortho if:**\n• Unable to achieve acceptable reduction\n• Intra-articular involvement\n• Significant comminution\n• Loss of reduction after splinting [1][3][4]","citation":[1,3,4],"next":"wrist-splinting","recommendation":"Reduce with Charnley technique. Sugar tong splint. Ortho follow-up 3-5 days if stable, urgent if intra-articular or unable to maintain reduction."}'::jsonb
WHERE id = 'wrist-colles' AND tree_id = 'wrist-injuries';

-- Node: wrist-scaphoid (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Scaphoid Fracture Management","body":"**Most commonly fractured carpal bone (60-70%)**\n\n**Clinical Diagnosis (even if X-rays negative):**\n• Snuffbox tenderness (dorsal)\n• Scaphoid tubercle tenderness (volar)\n• Pain with axial thumb loading\n• Decreased grip strength\n\n**Imaging:**\n• Initial: PA, lateral, oblique, **scaphoid view** (PA with ulnar deviation)\n• **Plain X-rays only 70% sensitive** — negative films do NOT exclude fracture\n• If clinical suspicion + negative X-rays → **immobilize and arrange MRI/CT in 3-5 days**\n• MRI preferred (detects bone marrow edema)\n• CT: alternative for immediate triage\n\n**Immobilization:**\n• **Thumb spica splint** (includes thumb IP joint)\n• Position: wrist extended 20-30°, thumb in \"soda can\" grasp\n• Even for **clinically suspected** fractures with negative X-rays\n\n**Why Aggressive Treatment:**\n• **Retrograde blood supply** via dorsal ridge vessels\n• Proximal pole at highest AVN risk (poor blood supply)\n• Complications: AVN, nonunion, SNAC wrist (scapholunate advanced collapse)\n\n**📞 Orthopedic Referral:**\n• **Urgent (24-48h):** Displaced fractures, proximal pole fractures\n• **Routine (3-7 days):** Non-displaced waist or distal pole fractures\n\n**Follow-Up Imaging:**\n• If initial X-rays negative but clinical suspicion: MRI at 3-5 days or repeat X-rays at 10-14 days [7][8][9][10]","citation":[7,8,9,10],"next":"wrist-splinting","recommendation":"Thumb spica splint for all clinically suspected scaphoid fractures, even if X-rays negative. Arrange MRI/CT in 3-5 days if initial films negative. Urgent ortho for proximal pole or displaced fractures."}'::jsonb
WHERE id = 'wrist-scaphoid' AND tree_id = 'wrist-injuries';

-- Node: wrist-peri-lunate (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Perilunate vs Lunate Dislocation","body":"**Two stages of the same injury spectrum:**\n\n**1. Perilunate Dislocation:**\n• Carpus (capitate + distal row) dislocates **dorsally**\n• Lunate maintains normal relationship with radius\n• **Lateral X-ray:** Lunate aligned with radius, capitate displaced dorsally\n\n**2. Lunate Dislocation (More Severe):**\n• Lunate dislocates **volarly** (rotates into carpal tunnel)\n• \"Spilled teacup\" sign on lateral view\n• **Lateral X-ray:** Lunate tilted volar, loss of relationship with radius\n\n**Mechanism:**\n• High-energy hyperextension injury (FOOSH with ulnar deviation)\n• MVA, fall from height\n• Progressive perilunate instability (Mayfield classification)\n\n**🚨 ACUTE CARPAL TUNNEL SYNDROME:**\n• **15-50% of cases**\n• Median nerve compressed by displaced lunate or hematoma\n• Paresthesias in thumb, index, middle, radial half of ring finger\n• **Resolve in 92% after reduction**\n\n**Associated Injuries:**\n• Trans-scaphoid perilunate fracture-dislocation (scaphoid fracture + dislocation)\n• Other carpal fractures\n\n**⚠️ REDUCE EMERGENTLY** to decompress median nerve and restore vascular supply [14][15][16]","citation":[14,15,16],"next":"wrist-peri-reduce","summary":"Perilunate: capitate dorsal; lunate dislocation: lunate volar into carpal tunnel; 15-50% acute CTS — reduce emergently","safetyLevel":"critical"}'::jsonb
WHERE id = 'wrist-peri-lunate' AND tree_id = 'wrist-injuries';

-- Node: wrist-druj (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"DRUJ (Distal Radioulnar Joint) Dislocation","body":"**DRUJ Dislocation — Easily Missed!**\n\n**Types:**\n• **Dorsal** (more common) — forced pronation + hyperextension\n• **Volar** — forced supination injury\n\n**Clinical Presentation:**\n• Ulnar-sided wrist pain\n• **Dorsal dislocation:** Prominent ulnar head dorsally\n• **Volar dislocation:** Absent ulnar head prominence\n• Limited/painful forearm rotation (pronation/supination)\n• Often subtle → frequently missed\n\n**Imaging:**\n• **True lateral wrist radiograph** essential\n• Compare DRUJ relationship bilaterally\n• **CT for subtle cases**\n\n**🚨 ASSOCIATED WITH:**\n• Distal radius fractures (Galeazzi fracture-dislocation)\n• Ulnar styloid base fractures (>2mm displacement disrupts TFCC)\n• **Always assess DRUJ with ANY distal radius or ulnar fracture**\n\n**Reduction Technique:**\n\n**Dorsal Dislocation:**\n1. Elbow at 90° flexion\n2. Apply longitudinal traction\n3. Direct dorsal pressure on ulnar head\n4. **Fully supinate forearm** (key maneuver)\n5. Feel/hear clunk as ulnar head reduces\n\n**Volar Dislocation:**\n1. Longitudinal traction\n2. **Fully pronate forearm**\n3. Direct pressure on ulnar head volarly\n\n**Post-Reduction:**\n• **Above-elbow cast** in position of stability\n• Dorsal dislocation: **supination**\n• Volar dislocation: **pronation**\n• Duration: 4-6 weeks\n\n**Stability Assessment:**\n• Test stability after reduction in neutral, pronation, supination\n• If unstable → may require K-wire fixation\n\n**📞 URGENT Orthopedic Referral:**\n• All DRUJ dislocations, especially if unstable or irreducible\n• Associated distal radius fractures\n\n**Pitfall:** Missing DRUJ dislocation with distal radius fracture (Galeazzi) → chronic pain, instability, limited rotation [18][19][20]","citation":[18,19,20],"next":"wrist-splinting","recommendation":"Reduce with longitudinal traction + forced supination (dorsal) or pronation (volar). Above-elbow cast in position of stability × 4-6 weeks. URGENT ortho referral, especially if unstable. Always check DRUJ with distal radius fractures."}'::jsonb
WHERE id = 'wrist-druj' AND tree_id = 'wrist-injuries';

-- Node: wrist-sl-dissoc (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Scapholunate Dissociation Management","body":"**Scapholunate Dissociation = Disruption of SL Interosseous Ligament**\n\n**Mechanism:** Forceful wrist hyperextension in ulnar deviation (FOOSH)\n\n**Clinical Presentation:**\n• Radial-sided wrist pain\n• Tenderness over scapholunate interval (1cm distal to Lister tubercle)\n• **Watson test (scaphoid shift test):** Clunk/pain with scaphoid displacement\n• Weakened grip strength\n\n**Imaging:**\n• **PA radiograph:**\n  - **Scapholunate gap ≥5mm** (\"Terry Thomas sign\" or \"David Letterman sign\")\n  - Normal gap: ≤2mm\n  - **Clenched fist PA view** accentuates gap\n\n• **Lateral radiograph:**\n  - Scapholunate angle >70° (normal: 30-60°)\n  - **DISI pattern** (dorsal intercalated segment instability) — lunate tilts dorsally\n\n• **MRI:** Useful preliminary diagnostic tool (shows ligament disruption)\n• **Wrist arthroscopy:** Gold standard\n\n**Complications if Untreated:**\n• Progressive carpal instability\n• **SLAC wrist** (scapholunate advanced collapse) — severe degenerative arthritis\n\n**Emergency Management:**\n1. Thumb spica splint\n2. Analgesia\n3. **URGENT hand specialist referral (24-48h)**\n\n**Surgical Timing:**\n• **Acute injuries (<6 weeks):** Primary ligament repair possible\n• **Chronic injuries:** More complex reconstruction required\n• Best outcomes with early intervention\n\n**📞 URGENT Orthopedic Referral (24-48h):**\n• All suspected or confirmed scapholunate dissociations\n• Time-sensitive — early surgery improves outcomes\n\n**Pitfall:** Dismissing as \"wrist sprain\" → progressive arthritis and disability [21][23][24]","citation":[21,23,24],"next":"wrist-splinting","recommendation":"Thumb spica splint. URGENT hand specialist referral (24-48h). Surgical repair within 6 weeks for best outcomes. Do not dismiss as simple sprain — risk of SLAC wrist."}'::jsonb
WHERE id = 'wrist-sl-dissoc' AND tree_id = 'wrist-injuries';

-- Node: wrist-imaging (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Wrist Imaging Approach","body":"**Standard Wrist Series:**\n• PA (posteroanterior)\n• Lateral (true lateral, not oblique)\n• Oblique\n\n**Special Views:**\n• **Scaphoid view:** PA with ulnar deviation + slight supination (for suspected scaphoid fracture)\n• **Carpal tunnel view:** Wrist hyperextended, hand supinated (for hook of hamate)\n• **Clenched fist PA:** Accentuates scapholunate dissociation\n\n**Systematic Review:**\n\n**PA View:**\n1. **Carpal arcs:** Three smooth curves (proximal carpal row, distal carpal row, distal carpal articular surfaces)\n   - Disruption suggests dislocation\n2. **Scapholunate gap:** Normal ≤2mm; ≥5mm = dissociation\n3. **Carpal alignment:** Lunate should be quadrilateral (triangular = dislocation)\n4. **Fracture lines**\n\n**Lateral View:**\n1. **Lunate alignment:** Lunate should articulate with radius (\"cup of radius\")\n   - Volar tilt = lunate dislocation (\"spilled teacup\")\n2. **Capitate-lunate-radius alignment:** Should form straight line\n   - Capitate displaced dorsally = perilunate dislocation\n3. **Scapholunate angle:** Normal 30-60°; >70° = dissociation/DISI\n4. **DRUJ relationship:** Ulnar head should align with sigmoid notch of radius\n\n**⚠️ ALWAYS ASSESS:**\n• **DRUJ on lateral view** (easily missed with distal radius fractures)\n• **Radial head-capitellum alignment** (if ulnar shaft fracture present → rule out Monteggia)\n\n**Advanced Imaging Indications:**\n• **MRI:** Suspected occult scaphoid or lunate fracture (3-5 days if initial X-rays negative), ligament tears, AVN\n• **CT:** Immediate triage for scaphoid fractures, complex carpal fractures, surgical planning, hook of hamate\n• **Wrist arthroscopy:** Gold standard for ligament injuries [2][27]","citation":[2,27],"next":"wrist-splinting","summary":"PA + lateral + oblique standard; scaphoid view with ulnar deviation; always check DRUJ on lateral and carpal arcs on PA"}'::jsonb
WHERE id = 'wrist-imaging' AND tree_id = 'wrist-injuries';

-- Node: wrist-splinting (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Wrist Splinting Techniques","body":"**Four Main Splint Types:**\n\n**1. Volar Splint**\n• **Indications:** Carpal fractures (except scaphoid), soft tissue injuries, stable distal radius\n• **Position:** Wrist 20° extension\n• **Coverage:** Volar forearm from proximal forearm to just proximal to MCP joints\n• **Advantage:** Allows thumb motion\n\n**2. Sugar Tong Splint**\n• **Indications:** Acute distal radius fractures, distal ulna fractures\n• **Position:** Forearm neutral rotation, wrist neutral to 10-20° extension, elbow 90°\n• **Coverage:** U-shaped from dorsal MCPs, along dorsal forearm, around elbow, along volar forearm to volar MCPs\n• **Advantage:** Limits forearm rotation (pronation/supination)\n\n**3. Thumb Spica Splint**\n• **Indications:** **Scaphoid fractures** (confirmed or suspected), first metacarpal fractures, de Quervain tenosynovitis\n• **Position:** Forearm neutral, wrist extended 20-30°, thumb in \"soda can\" grasp position\n• **Coverage:** Radial forearm to just past thumb IP joint\n• **Critical:** Immobilize thumb IP joint (some protocols allow IP free for distal pole scaphoid)\n• **⚠️ Use for ALL suspected scaphoid fractures** (even if X-rays negative)\n\n**4. Ulnar Gutter Splint**\n• **Indications:** 4th/5th metacarpal fractures, ulnar-sided wrist injuries, ulnar styloid fractures\n• **Position:** Wrist neutral to slight extension, slight ulnar deviation\n• **Coverage:** Ulnar forearm to fingertips of 4th and 5th digits\n• **Position:** MCP 70-90° flexion, PIP/DIP slight flexion\n\n**Post-Splint Check:**\n• Capillary refill <2 seconds\n• Sensation intact (median, radial, ulnar distributions)\n• Finger movement (flexion/extension)\n• No excessive tightness or pressure points\n\n**Splinting Pearls:**\n• Apply over stockinette + padding (especially bony prominences)\n• Plaster: 8-10 layers; fiberglass: 3-4 layers\n• Splint should cover 1/2 to 2/3 circumference (not circumferential)\n• Edges smooth and rolled to prevent skin irritation [2][28][29][30]","citation":[2,28,29,30],"next":"wrist-complications","summary":"Sugar tong for distal radius; thumb spica for scaphoid (even if XR negative); ulnar gutter for 4th/5th MC"}'::jsonb
WHERE id = 'wrist-splinting' AND tree_id = 'wrist-injuries';

COMMIT;